#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long power(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, l;
    cin >> n >> k >> l;

    vector<long long> factorials(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        factorials[i] = (factorials[i - 1] * i) % mod;
    }

    vector<vector<long long>> dpTable(2 * n + 1, vector<long long>(2 * n + 2, 0));
    dpTable[0][0] = 1;

    for (int i = 1; i <= 2 * n; i++) {
        for (int j = 0; j <= min(i, n); j++) {
            if (j > 0) {
                dpTable[i][j] = (dpTable[i][j] + dpTable[i - 1][j - 1]) % mod;
            }
            dpTable[i][j] = (dpTable[i][j] + dpTable[i - 1][j + 1] * (j + 1) % mod) % mod;
        }
    }

    long long totalAns = 0;
    for (int i = k; i <= 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            totalAns = (totalAns + dpTable[i][j] * dpTable[2 * n - i][j] % mod * factorials[j] % mod) % mod;
        }
    }

    long long invA = power(dpTable[2 * n][0], mod - 2);
    long long invB = power(2 * n + 1, mod - 2);
    cout << (l * totalAns % mod * invA % mod * invB % mod) << "\n";

    return 0;
}
